<?php
namespace App\Services; use App\Core\Database; use RuntimeException; class DrawService{public function run(int $fundId,int $managerId):array{$db=Database::pdo();$fund=$db->prepare('SELECT * FROM funds WHERE id=?');$fund->execute([$fundId]);$f=$fund->fetch();if(!$f)throw new RuntimeException('صندوق یافت نشد.');$sql="SELECT u.id, CONCAT(u.first_name,' ',u.last_name) name FROM fund_members fm JOIN users u ON u.id=fm.user_id WHERE fm.fund_id=? AND fm.status='active' AND u.status='active' AND u.id NOT IN(SELECT winner_user_id FROM winners WHERE fund_id=?)"; if($f['exclude_debtors_from_draw'])$sql.=" AND u.id NOT IN(SELECT user_id FROM installments WHERE fund_id=? AND status IN('unpaid','partial','overdue'))"; $st=$db->prepare($sql);$params=$f['exclude_debtors_from_draw']?[$fundId,$fundId,$fundId]:[$fundId,$fundId];$st->execute($params);$participants=$st->fetchAll(); if(!$participants)throw new RuntimeException('شرکت‌کننده واجد شرایط وجود ندارد.');$seed=bin2hex(random_bytes(32));$index=random_int(0,count($participants)-1);$winner=$participants[$index];$db->beginTransaction();$d=$db->prepare('INSERT INTO draws(fund_id,draw_uid,seed,participants_snapshot,winner_user_id,executed_by,executed_at) VALUES(?,?,?,?,?,?,NOW())');$uid='DRAW-'.date('Ymd-His').'-'.random_int(1000,9999);$d->execute([$fundId,$uid,$seed,json_encode($participants,JSON_UNESCAPED_UNICODE),$winner['id'],$managerId]);$drawId=(int)$db->lastInsertId();$p=$db->prepare('INSERT INTO draw_participants(draw_id,user_id,eligible) VALUES(?,?,1)');foreach($participants as $row)$p->execute([$drawId,$row['id']]);$w=$db->prepare('INSERT INTO winners(fund_id,draw_id,winner_user_id,won_at) VALUES(?,?,?,NOW())');$w->execute([$fundId,$drawId,$winner['id']]);$db->commit();AuditLogger::log('draw_run','draws',$drawId,['winner'=>$winner,'seed'=>$seed]);return compact('drawId','uid','seed','participants','winner');}}
